var Beep = new Audio();

const BeepSource = {
  mute: 'data:audio/mpeg;base64,',
  ding: '/static/audio/ding.mp3',
  error: '/static/audio/error2.mp3'
} 

const registerBeep = function() { 
  Beep = new Audio(BeepSource.mute); 
  Beep.play();
}

const playBeep = function (what) {
  Beep.src = BeepSource[what];
  Beep.play();
}